pub fn ranges(xs: List[Int]) -> Str {
  let u = xs.unique().sort()
  let n = u.len()
  var parts: List[Str] = []
  var i = 0
  while i < n {
    var j = i
    while j + 1 < n and u.get_or(j + 1, 0) == u.get_or(j, 0) + 1 {
      j = j + 1
    }
    let a = u.get_or(i, 0)
    let b = u.get_or(j, 0)
    if j - i >= 2 {
      parts = parts.push(a.to_str() + "-" + b.to_str())
    } else if j == i {
      parts = parts.push(a.to_str())
    } else {
      parts = parts.push(a.to_str())
      parts = parts.push(b.to_str())
    }
    i = j + 1
  }
  return parts.join(",")
}
